final_sql:
SELECT CAST(ROUND((
    SELECT COUNT(*) FROM Player p2 LEFT JOIN Player_Attributes AS j_Player_Attributes ON p2.player_api_id = j_Player_Attributes.player_api_id WHERE p2.height < 180 AND j_Player_Attributes.overall_rating > 70
), 10) * 100 / 100 AS DECIMAL(10,2)) AS percentage
